const dictionaries={fr,en,ar};
for(const [code,translations] of Object.entries(featuredDestinationText)){
  Object.values(dictionaries).forEach((dictionary,index)=>{
    const [country,city,landmark]=translations[index];
    dictionary['destCountry'+code]=country;
    dictionary['destCity'+code]=city;
    dictionary['destTag'+code]=landmark;
  });
}
function readStorage(key,fallback){try{return JSON.parse(localStorage.getItem(key))??fallback;}catch{return fallback;}}
let lang=readStorage('dzfly-language','fr');if(!dictionaries[lang])lang='fr';
const t=k=>dictionaries[lang][k]??fr[k]??k;
let state={service:'flights',trip:'round',origin:'ALG',destination:'',departure:dateAfter(14),returnDate:dateAfter(21),adults:1,children:0,infants:0,rooms:1,cabin:'economy',direct:false,baggage:false,legOrigin:'IST',legDestination:'CDG',legDate:dateAfter(21)};
let searched=null,offers=[],focusBeforeDialog=null,travelerDraft=null,lastDraft=null;
const stored=readStorage('dzfly-trips',[]);
let trips=Array.isArray(stored)?stored.filter(x=>x&&typeof x.id==='string'&&x.search&&airport(x.search.origin)&&airport(x.search.destination)).slice(0,30):[];
const locale=()=>lang==='ar'?'ar-DZ':lang==='en'?'en-GB':'fr-FR';
const money=v=>`${new Intl.NumberFormat(locale(),{maximumFractionDigits:0}).format(v)} DZD`;
const dateLabel=d=>new Date(`${d}T12:00:00`).toLocaleDateString(locale(),{day:'numeric',month:'short',year:'numeric'});
const pax=s=>s.adults+s.children+s.infants;
function paintIcons(root=document){$$('[data-icon]',root).forEach(e=>e.innerHTML=icon(e.dataset.icon));}
function renderFields(){
 const flight=state.service==='flights',a=airport(state.origin),b=airport(state.destination);
 $('#home').dataset.mode=state.service;
 $('#hero-location').textContent=({fr:flight?'Au-dessus de la Méditerranée':'Une parenthèse en Méditerranée',en:flight?'Above the Mediterranean':'A Mediterranean escape',ar:flight?'فوق البحر الأبيض المتوسط':'إقامة على ضفاف المتوسط'})[lang];
 const origin=flight?`<button class="field" type="button" data-airport="origin"><span data-icon="plane"></span><span class="field-copy"><small>${t('origin')}</small><strong>${esc(a.city)} (${a.code})</strong></span></button><button class="swap" type="button" data-action="swap" aria-label="${t('swap')}">${icon('swap')}</button>`:'';
 $('#search-fields').innerHTML=origin+`<button class="field destination-field" type="button" data-airport="destination"><span data-icon="${flight?'plane':'pin'}"></span><span class="field-copy"><small>${t('destination')}</small><strong class="${b?'':'placeholder'}">${b?`${esc(b.city)}${flight?` (${b.code})`:''}`:t('chooseDestination')}</strong></span></button><div class="field date-field"><span data-icon="calendar"></span><div class="date-pair"><label><span>${t(flight?'departure':'checkin')}</span><input id="departure-date" type="date" aria-label="${t(flight?'departure':'checkin')}" required min="${todayISO()}" value="${state.departure}"></label>${(state.trip==='round'||!flight)?`<label><span>${t(flight?'returnDate':'checkout')}</span><input id="return-date" type="date" aria-label="${t(flight?'returnDate':'checkout')}" required min="${dateAfter(1,state.departure)}" value="${state.returnDate}"></label>`:''}</div></div><button class="field travelers-field" type="button" data-action="travelers"><span data-icon="users"></span><span class="field-copy"><small>${t(flight?'travelers':'guests')}</small><strong>${pax(state)} ${t(pax(state)===1?'traveler':'travelersPlural')}, ${flight?t(state.cabin):state.rooms+' '+t('room')}</strong></span></button><button class="primary-button search-submit" type="submit">${icon('search')}<span>${t('search')}</span></button>`;
 for(const group of [$('.trip-types'),$('.search-options')]){group.hidden=false;group.classList.toggle('is-reserved',!flight);group.inert=!flight;}
 $$('[data-trip]').forEach(b=>{b.classList.toggle('active',b.dataset.trip===state.trip);b.setAttribute('aria-pressed',String(b.dataset.trip===state.trip));});
 const options=code=>airports.map(a=>`<option value="${a.code}" ${a.code===code?'selected':''}>${esc(a.city)} (${a.code})</option>`).join('');
 $('#extra-legs').innerHTML=state.trip==='multi'?`<div class="extra-leg${flight?'':' is-reserved'}" ${flight?'':'inert'}><label>${t('leg2')} · ${t('from')}<select id="leg-origin" ${flight?'':'disabled'}>${options(state.legOrigin)}</select></label><label>${t('to')}<select id="leg-destination" ${flight?'':'disabled'}>${options(state.legDestination)}</select></label><label>${t('departure')}<input type="date" id="leg-date" min="${state.departure}" value="${state.legDate}" required ${flight?'':'disabled'}></label></div>`:'';
 $('#direct').checked=state.direct;$('#baggage').checked=state.baggage;paintIcons($('#search-form'));
}
function applyLanguage(){
 document.documentElement.lang=lang;document.documentElement.dir=lang==='ar'?'rtl':'ltr';
 $$('[data-t]').forEach(e=>e.innerHTML=t(e.dataset.t));$('#language-code').textContent=lang==='ar'?'ع':lang.toUpperCase();
 syncDrawer();
 renderFields();renderFAQs();if(searched)renderResults();paintIcons();updateCount();
}
function renderFAQs(){
 const questions=lang==='en'?[
 ['Can I buy a ticket now?','This discovery version lets you explore the journey and save example itineraries. No live bookings, payments or ticket issuance are available yet.'],
 ['How will I pay for my journey?','CIB, Edahabia and cash options are planned. Availability and reservation time limits will be confirmed before commercial launch.'],
 ['Where can I find my saved trips?','Open My trips in the menu. Drafts are stored on this browser and this device. You can download or delete each draft.'],
 ['Does saving an itinerary hold the price?','No. Example fares are fictional. Saving a draft does not hold a seat, lock a price or create an airline reservation.']
 ]:lang==='ar'?[
 ['هل يمكنني شراء تذكرة الآن؟','تتيح النسخة التجريبية استكشاف المسار وحفظ أمثلة للرحلات. لا تتوفر حجوزات حقيقية أو مدفوعات أو إصدار تذاكر بعد.'],
 ['كيف سأدفع ثمن الرحلة؟','نخطط لخيارات الدفع ببطاقات CIB والذهبية ونقداً. ستُحدد الشروط ومهل الحجز قبل الإطلاق التجاري.'],
 ['أين أجد رحلاتي المحفوظة؟','افتح قسم رحلاتي. تُحفظ المسودات في هذا المتصفح وعلى هذا الجهاز. يمكنك تنزيلها أو حذفها.'],
 ['هل حفظ المسار يضمن السعر؟','لا. الأسعار المعروضة افتراضية. حفظ المسودة لا يحجز مقعداً ولا يثبت سعراً ولا ينشئ حجزاً لدى شركة طيران.']
 ]:[
 ['Puis-je acheter un billet dès maintenant ?','Cette version découverte permet de tester le parcours et d’enregistrer des exemples d’itinéraires. Les réservations réelles, le paiement et l’émission des billets ne sont pas encore activés.'],
 ['Comment pourrai-je payer mon voyage ?','Les parcours CIB, Edahabia et espèces sont prévus. Leur disponibilité, les zones de livraison et les délais de réservation seront précisés avant l’ouverture commerciale.'],
 ['Où retrouver mes voyages enregistrés ?','Ouvrez Mes voyages depuis le menu. Vos brouillons sont conservés dans ce navigateur, sur cet appareil. Vous pouvez les télécharger ou les supprimer.'],
 ['Enregistrer un itinéraire garantit-il son prix ?','Non. Les prix des exemples sont fictifs. Un brouillon ne bloque ni place ni tarif et ne constitue pas une réservation auprès d’une compagnie.']
 ];
 $('#faq-list').innerHTML=questions.map(([q,a])=>`<details><summary>${q}</summary><p>${a}</p></details>`).join('');
}
function setService(service){
 if(service===state.service)return;
 settleScroll();
 state.service=service;
 $$('[data-service]').forEach(b=>{const active=b.dataset.service===service;b.classList.toggle('active',active);b.classList.toggle('is-active',active);if(b.getAttribute('role')==='tab')b.setAttribute('aria-selected',String(active));});
 syncDrawer();
 $('#search-error').hidden=true;renderFields();animateSearchFields($('#search-fields'));
 if(searched){$('#results').hidden=true;searched=null;}
}
function showDialog(title,body,kind='info'){
 const d=$('#dialog');if(!d.open)focusBeforeDialog=document.activeElement;
 d.dataset.kind=kind;$('#dialog-content').innerHTML=`<div class="dialog-header"><h2 id="dialog-title">${title}</h2><button class="icon-button" data-action="close" aria-label="${t('close')}">${icon('close')}</button></div>${body}`;
 if(!d.open)d.showModal();paintIcons(d);const field=$('input:not([type=radio]),select',d);if(field)field.focus();
}
function closeDialog(){const d=$('#dialog');if(d.open)d.close();}
const drawer=$('#menu-drawer'),drawerTrigger=$('#menu-trigger');
function syncDrawer(){
 drawerTrigger.setAttribute('aria-label',t('drawerOpen'));
 $('#menu-close').setAttribute('aria-label',t('drawerClose'));
 $$('[data-lang]',drawer).forEach(button=>button.setAttribute('aria-pressed',String(button.dataset.lang===lang)));
 $$('[data-service]',drawer).forEach(button=>{
   if(button.dataset.service===state.service)button.setAttribute('aria-current','true');
   else button.removeAttribute('aria-current');
 });
}
function openDrawer(){
 if(drawer.open)return;
 settleScroll();
 drawer.showModal();
 drawerTrigger.setAttribute('aria-expanded','true');
}
function closeDrawer(){
 if(!drawer.open)return;
 drawer.close();
 drawerTrigger.setAttribute('aria-expanded','false');
}
drawer.addEventListener('cancel',e=>{e.preventDefault();closeDrawer();});
drawer.addEventListener('click',e=>{
 if(e.target===drawer){
   const r=drawer.getBoundingClientRect();
   if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeDrawer();
   return;
 }
 const b=e.target.closest('button,a');
 if(!b)return;
 if(b.matches('a')&&(e.ctrlKey||e.metaKey||e.altKey||e.shiftKey))return;
 if(b.matches('a,[data-service],[data-action="help"],[data-action="trips"]'))closeDrawer();
});
$('#dialog').addEventListener('close',()=>{if(focusBeforeDialog?.isConnected)focusBeforeDialog.focus();});
$('#dialog').addEventListener('click',e=>{if(e.target===$('#dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeDialog();}});
function airportDialog(field){
 showDialog(t(field==='origin'?'chooseOrigin':'chooseArrival'),`<label class="dialog-search">${icon('search')}<input id="airport-search" type="search" placeholder="${t('searchAirport')}" aria-label="${t('searchAirport')}" autocomplete="off"></label><div id="airport-options" class="airport-list"></div>`,'airport');
 const render=query=>{const q=query.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();const arabicAliases={الجزائر:'ALG',وهران:'ORN',قسنطينة:'CZL',باريس:'CDG',اسطنبول:'IST',إسطنبول:'IST',دبي:'DXB',بالي:'DPS',تونس:'TUN'};const results=airports.filter(a=>`${a.city} ${a.name} ${a.code} ${a.country}`.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().includes(q)||arabicAliases[query]===a.code);$('#airport-options').innerHTML=results.length?results.map(a=>`<button class="airport-option" data-choose-airport="${a.code}" data-airport-field="${field}"><span>${icon('plane')}</span><span><strong>${esc(a.city)}</strong><small>${esc(a.name)} · ${esc(a.country)}</small></span><span class="airport-code">${a.code}</span></button>`).join(''):`<p class="no-results">${t('noAirport')}</p>`;};
 render('');$('#airport-search').addEventListener('input',e=>render(e.target.value.trim()));
}
function travelersDialog(){travelerDraft={adults:state.adults,children:state.children,infants:state.infants,rooms:state.rooms,cabin:state.cabin};renderTravelers();}
function renderTravelers(){
 const rows=[['adults','adultsSub'],['children','childrenSub'],...(state.service==='flights'?[['infants','infantsSub']]:[['rooms',null]])];
 showDialog(t(state.service==='flights'?'travelers':'guests'),`<p class="dialog-intro">${t('maxTravelers')}</p>${rows.map(([key,sub])=>`<div class="counter-row"><div><strong>${t(key)}</strong>${sub?`<small>${t(sub)}</small>`:''}</div><div class="counter"><button data-count="${key}" data-delta="-1" aria-label="− ${t(key)}" ${travelerDraft[key]<=(key==='adults'||key==='rooms'?1:0)?'disabled':''}>−</button><output>${travelerDraft[key]}</output><button data-count="${key}" data-delta="1" aria-label="+ ${t(key)}" ${key==='rooms'?travelerDraft.rooms>=5?'disabled':'':pax(travelerDraft)>=9||(key==='infants'&&travelerDraft.infants>=travelerDraft.adults)?'disabled':''}>+</button></div></div>`).join('')}${state.service==='flights'?`<label class="select-row">${t('cabin')}<select id="cabin">${['economy','business','first'].map(k=>`<option value="${k}" ${travelerDraft.cabin===k?'selected':''}>${t(k)}</option>`).join('')}</select></label>`:''}<div class="dialog-footer"><button class="primary-button" data-action="apply-travelers">${t('done')}${icon('check')}</button></div>`,'travelers');
}
function errorFor(key){return t(({airport:'airportError',same:'sameError',departure:'departureError',return:'returnError',travelers:'travelersError',leg:'legError',legDate:'legDateError'})[key]);}
function syncForm(){state.departure=$('#departure-date').value;state.returnDate=$('#return-date')?.value??state.returnDate;state.direct=$('#direct').checked;state.baggage=$('#baggage').checked;if(state.trip==='multi'){state.legOrigin=$('#leg-origin').value;state.legDestination=$('#leg-destination').value;state.legDate=$('#leg-date').value;}}
$('#search-form').addEventListener('submit',e=>{e.preventDefault();syncForm();const error=validateSearch(state);if(error){$('#search-error').textContent=errorFor(error);$('#search-error').hidden=false;return;}$('#search-error').hidden=true;searched={...state};offers=demoOffers(searched);const query=new URLSearchParams(Object.entries(searched).map(([k,v])=>[k,String(v)]));history.replaceState(null,'',`?${query}#results`);renderResults();scrollToElement('#results');});
function renderResults(sort='price'){
 const s=searched;if(!s)return;const a=airport(s.origin),b=airport(s.destination),hotel=s.service==='stays';
 const dates=`${dateLabel(s.departure)}${s.trip==='round'||hotel?' — '+dateLabel(s.returnDate):''}`;
 const title=hotel?`${t('hotelTitle')} · ${b.city}`:`${a.city} ${lang==='ar'?'←':'→'} ${b.city}`;
 const result=$('#results');result.hidden=false;
 result.innerHTML=`<div class="results-heading"><div><p class="eyebrow dark">${t('discovery')}</p><h2 id="results-title">${esc(title)}</h2><p>${dates} · ${pax(s)} ${t(pax(s)===1?'traveler':'travelersPlural')}${s.trip==='multi'&&!hotel?` · ${esc(airport(s.legOrigin).city)} → ${esc(airport(s.legDestination).city)} (${dateLabel(s.legDate)})`:''}</p></div><select class="results-sort" id="sort-results" aria-label="${t('cheapest')}"><option value="price">${t('cheapest')}</option>${!hotel?`<option value="time">${t('earliest')}</option><option value="duration">${t('fastest')}</option>`:''}</select></div><div class="info-notice">${t(hotel?'hotelDemo':'demoNotice')}</div><div id="offer-list"></div><button class="text-link" data-action="modify">${t('modify')} ${icon('arrow')}</button>`;
 const sorted=hotel?[{id:'hotel-1',price:12500,name:'hotelCenter'},{id:'hotel-2',price:16900,name:'hotelRelax'},{id:'hotel-3',price:21400,name:'hotelComfort'}]:[...offers].sort((x,y)=>sort==='time'?x.departure.localeCompare(y.departure):sort==='duration'?Number(x.duration.replace(/\D/g,''))-Number(y.duration.replace(/\D/g,'')):x.price-y.price);
 $('#sort-results').value=sort;
 $('#offer-list').innerHTML=sorted.length?sorted.map(o=>hotel?`<article class="offer hotel-offer"><div class="hotel-symbol">${icon('hotel')}</div><div><h3>${t(o.name)}</h3><p>${esc(b.city)} · ${s.rooms} ${t('room')}<br>${t('hotelDescription')}</p></div><div class="offer-price"><small>${t('nightPrice')}</small><strong dir="ltr">${money(o.price)}</strong><button class="primary-button" data-select-offer="${o.id}">${t('prepareTrip')}${icon('arrow')}</button></div></article>`:`<article class="offer"><div class="offer-airline"><span class="airline-symbol">${icon('plane')}</span><span><strong>${t('exampleFlight')}</strong><small>DZ FLY · ${t(s.cabin)}</small></span></div><div class="flight-route" dir="ltr"><div class="flight-time"><strong>${o.departure}</strong><small>${a.code} · ${esc(a.city)}</small></div><div class="route-line"><small>${o.duration}</small><div></div><small>${t(o.stops?'stopLabel':'directLabel')}</small></div><div class="flight-time"><strong>${o.arrival}</strong><small>${b.code} · ${esc(b.city)}</small></div></div><div class="offer-tags"><span>${t(o.baggage?'luggageIncluded':'cabinOnly')}</span><span>${t(s.trip==='round'?'roundLabel':s.trip==='multi'?'multiLabel':'oneLabel')}</span></div><div class="offer-price"><small>${t('perPerson')}</small><strong dir="ltr">${money(o.price)}</strong><button class="primary-button" data-select-offer="${o.id}">${t('prepareTrip')}${icon('arrow')}</button></div></article>`).join(''):`<p class="no-results">${t('emptyResults')}</p>`;
 $('#sort-results').addEventListener('change',e=>renderResults(e.target.value));
}
const nights=s=>Math.max(1,Math.round((new Date(s.returnDate+'T12:00:00')-new Date(s.departure+'T12:00:00'))/86400000));
function summary(s,o){const hotel=s.service==='stays';return `<div class="trip-summary"><h3>${hotel?esc(airport(s.destination).city):`${esc(airport(s.origin).city)} → ${esc(airport(s.destination).city)}`}</h3><p>${dateLabel(s.departure)}${s.trip==='round'||hotel?' — '+dateLabel(s.returnDate):''}<br>${pax(s)} ${t(pax(s)===1?'traveler':'travelersPlural')}${hotel?' · '+nights(s)+' '+t('nights'):' · '+t(s.cabin)}${s.trip==='multi'&&!hotel?`<br>${esc(airport(s.legOrigin).city)} → ${esc(airport(s.legDestination).city)} · ${dateLabel(s.legDate)}`:''}</p><p>${t('total')} : <strong dir="ltr">${money(hotel?o.price*nights(s)*s.rooms:totalFare(o,s))}</strong></p></div>`;}
function prepareOffer(id){
 const hotel=searched.service==='stays';const o=hotel?{id,price:({'hotel-1':12500,'hotel-2':16900,'hotel-3':21400})[id]}:offers.find(o=>o.id===id);if(!o||!o.price)return;
 lastDraft={id:'DRAFT-'+(crypto.randomUUID?.()??Date.now().toString()).slice(0,8).toUpperCase(),search:{...searched},offer:{...o},createdAt:new Date().toISOString(),status:'draft'};
 showDialog(t('tripPreparation'),`<p class="info-notice">${t('savedOnly')}</p>${summary(searched,o)}<form id="draft-form"><label class="select-row">${t('tripName')}<input class="text-input" id="trip-name" maxlength="80" placeholder="${t('tripNamePlaceholder')}" autocomplete="off"></label><label class="select-row">${t('paymentTitle')}</label><div class="payment-options">${[['card','wallet'],['cash','pin'],['pickup','hotel']].map(([v,i],n)=>`<label class="payment-choice"><input type="radio" name="payment" value="${v}" ${n===0?'checked':''}>${icon(i)}<span>${t(v)}</span></label>`).join('')}</div><p class="dialog-intro">${t('paymentInfo')}</p><button class="primary-button full-width" type="submit">${t('save')}${icon('check')}</button></form>`,'prepare');
 $('#draft-form').addEventListener('submit',e=>{e.preventDefault();lastDraft.name=$('#trip-name').value.trim();lastDraft.payment=$('input[name="payment"]:checked').value;trips.unshift(lastDraft);trips=trips.slice(0,30);let ok=true;try{localStorage.setItem('dzfly-trips',JSON.stringify(trips));}catch{ok=false;}updateCount();showDialog(t('savedTitle'),`<p class="dialog-intro">${ok?t('savedBody'):t('saveFailed')}</p>${summary(lastDraft.search,lastDraft.offer)}<button class="primary-button full-width" data-action="trips">${t('viewTrips')}${icon('arrow')}</button><div class="dialog-footer"><button class="text-link" data-export="${lastDraft.id}">${t('download')}${icon('arrow')}</button></div>`,'saved');});
}
function updateCount(){const c=$('.trip-count');c.textContent=trips.length;c.hidden=!trips.length;}
function showTrips(){showDialog(t('myTrips'),trips.length?`<p class="dialog-intro">${t('savedOnly')}</p>${trips.map(d=>`<article class="saved-trip"><div class="saved-trip-top"><h3>${esc(d.name||`${airport(d.search.origin).city} → ${airport(d.search.destination).city}`)}</h3><span class="status-pill">${t('draft')}</span></div><p>${esc(d.id)} · ${dateLabel(d.search.departure)}</p><p>${pax(d.search)} ${t(pax(d.search)===1?'traveler':'travelersPlural')} · ${t(d.payment||'card')}</p><div class="saved-trip-actions"><button data-export="${esc(d.id)}">${t('download')}</button><button data-remove="${esc(d.id)}">${t('remove')}</button></div></article>`).join('')}`:`<div class="empty-state">${icon('ticket')}<h3>${t('emptyTrips')}</h3><p>${t('emptyTripsSub')}</p><button class="primary-button" data-action="explore">${t('start')}${icon('arrow')}</button></div>`,'trips');}
function exportTrip(id){const d=trips.find(x=>x.id===id);if(!d)return;const s=d.search;const hotel=s.service==='stays';const text=[t('exportTitle'),'',t('exportDisclaimer'),'',d.name||'',d.id,hotel?airport(s.destination).city:`${airport(s.origin).city} → ${airport(s.destination).city}`,`${t('dates')}: ${s.departure}${s.trip==='round'||hotel?' / '+s.returnDate:''}`,s.trip==='multi'&&!hotel?`${airport(s.legOrigin).city} → ${airport(s.legDestination).city} / ${s.legDate}`:'',`${t('travelers')}: ${pax(s)}`,`${t('total')}: ${money(hotel?d.offer.price*nights(s)*s.rooms:totalFare(d.offer,s))}`,`${t('payment')}: ${t(d.payment)}`].filter(x=>x!==undefined).join('\n');const url=URL.createObjectURL(new Blob(['\uFEFF'+text],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=`DZ-FLY-${d.id}.txt`;a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);}
let toastTimer;function toast(text){clearTimeout(toastTimer);$('#toast').textContent=text;$('#toast').hidden=false;toastTimer=setTimeout(()=>$('#toast').hidden=true,3500);}
document.addEventListener('change',e=>{
 if(e.target.id==='cabin'&&travelerDraft)travelerDraft.cabin=e.target.value;
 if(e.target.id==='departure-date'){state.departure=e.target.value;if(state.returnDate<=state.departure)state.returnDate=dateAfter(7,state.departure);if(state.legDate<state.departure)state.legDate=dateAfter(3,state.departure);const ret=$('#return-date');if(ret){ret.min=dateAfter(1,state.departure);ret.value=state.returnDate;}const leg=$('#leg-date');if(leg){leg.min=state.departure;leg.value=state.legDate;}}
 if(e.target.id==='return-date')state.returnDate=e.target.value;
 if(e.target.id==='direct')state.direct=e.target.checked;
 if(e.target.id==='baggage')state.baggage=e.target.checked;
 if(e.target.id==='leg-origin')state.legOrigin=e.target.value;
 if(e.target.id==='leg-destination')state.legDestination=e.target.value;
 if(e.target.id==='leg-date')state.legDate=e.target.value;
});
document.addEventListener('click',e=>{
 const b=e.target.closest('button,a');if(!b)return;
 if(b.dataset.service){closeDialog();setService(b.dataset.service);if(!b.closest('.hero'))scrollToElement('#search',{block:'center'});return;}
 if(b.dataset.trip){state.trip=b.dataset.trip;renderFields();return;}
 if(b.dataset.airport){airportDialog(b.dataset.airport);return;}
 if(b.dataset.chooseAirport){state[b.dataset.airportField]=b.dataset.chooseAirport;if(b.dataset.airportField==='destination')state.legOrigin=b.dataset.chooseAirport;closeDialog();renderFields();return;}
 if(b.dataset.destination){state.destination=b.dataset.destination;state.legOrigin=b.dataset.destination;setService('flights');renderFields();scrollToElement('#search',{block:'center'});return;}
 if(b.dataset.count){const key=b.dataset.count;travelerDraft[key]+=Number(b.dataset.delta);if(travelerDraft.infants>travelerDraft.adults)travelerDraft.infants=travelerDraft.adults;renderTravelers();return;}
 if(b.dataset.selectOffer){prepareOffer(b.dataset.selectOffer);return;}
 if(b.dataset.export){exportTrip(b.dataset.export);return;}
 if(b.dataset.remove){showDialog(t('confirmRemove'),`<p class="dialog-intro">${t('confirmRemoveSub')}</p><div class="dialog-footer"><button class="text-link" data-action="trips">${t('cancel')}</button><button class="primary-button" style="margin-inline-start:20px" data-confirm-remove="${esc(b.dataset.remove)}">${t('remove')}</button></div>`,'remove');return;}
 if(b.dataset.confirmRemove){const next=trips.filter(d=>d.id!==b.dataset.confirmRemove);try{localStorage.setItem('dzfly-trips',JSON.stringify(next));}catch{}trips=next;updateCount();showTrips();toast(t('removed'));return;}
 if(b.dataset.lang){lang=b.dataset.lang;try{localStorage.setItem('dzfly-language',JSON.stringify(lang));}catch{}closeDialog();applyLanguage();return;}
 const action=b.dataset.action;
 if(action==='close')closeDialog();
 if(action==='swap'){if(state.destination){[state.origin,state.destination]=[state.destination,state.origin];renderFields();}}
 if(action==='travelers')travelersDialog();
 if(action==='apply-travelers'){Object.assign(state,travelerDraft);closeDialog();renderFields();}
 if(action==='trips')showTrips();
 if(action==='explore'){closeDialog();setService('flights');scrollToElement('#search',{block:'center'});}
 if(action==='modify')scrollToElement('#search',{block:'center'});
 if(action==='help')showDialog(t('helpTitle'),`<p class="dialog-intro">${t('helpBody')}</p><button class="primary-button" data-action="faq">${t('helpFaq')}${icon('arrow')}</button>`);
 if(action==='faq'){closeDialog();scrollToElement('#faq');}
 if(action==='how')showDialog(t('how'),`<div class="info-block">${t('howBody')}</div>`);
 if(action==='privacy')showDialog(t('privacy'),`<div class="info-block">${t('privacyBody')}</div>`);
 if(action==='terms')showDialog(t('terms'),`<div class="info-block">${t('termsBody')}</div>`);
 if(action==='language')showDialog(t('language'),['fr','en','ar'].map(l=>`<button class="language-option ${l===lang?'active':''}" data-lang="${l}"><span>${{fr:'Français',en:'English',ar:'العربية'}[l]}</span><span>${l===lang?icon('check'):l.toUpperCase()}</span></button>`).join(''),'language');
 if(action==='menu')openDrawer();
 if(action==='close-menu')closeDrawer();
});
$('#year').textContent=new Date().getFullYear();
const params=new URLSearchParams(location.search);if(params.has('destination')){
 const candidate=normalizeSearch({...state,...Object.fromEntries(params)});
 if(['flights','stays'].includes(candidate.service)&&['round','one','multi'].includes(candidate.trip)&&['economy','business','first'].includes(candidate.cabin)&&!validateSearch(candidate)){
  state=candidate;searched={...candidate};offers=demoOffers(searched);
 }
}
applyLanguage();$$('[data-service]').forEach(b=>{const active=b.dataset.service===state.service;b.classList.toggle('active',active);b.classList.toggle('is-active',active);if(b.getAttribute('role')==='tab')b.setAttribute('aria-selected',String(active));});
let resizeTimer;addEventListener('resize',()=>{clearTimeout(resizeTimer);resizeTimer=setTimeout(renderFields,120);});
